for i,v in enumerate(SBOX): INV_SBOX[v]=i
RCON=[0x00,0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36]

def xtime(a): return ((a<<1)^0x1b)&0xff if a&0x80 else (a<<1)&0xff
def mul(a,b):
    r=0
    for _ in range(8):
        if b&1: r^=a
        a=xtime(a); b>>=1
    return r

def key_expansion(key):
    Nk=8; Nr=14
    w=[list(key[4*i:4*i+4]) for i in range(Nk)]
    for i in range(Nk, 4*(Nr+1)):
        t=list(w[i-1])
        if i%Nk==0:
            t=[SBOX[t[1]]^RCON[i//Nk], SBOX[t[2]], SBOX[t[3]], SBOX[t[0]]]
        elif i%Nk==4:
            t=[SBOX[x] for x in t]
        w.append([w[i-Nk][j]^t[j] for j in range(4)])
    return w

def add_round_key(s,w,r):
    for c in range(4):
        for rr in range(4):
            s[rr][c]^=w[r*4+c][rr]

def inv_sub_bytes(s):
    for r in range(4):
        for c in range(4): s[r][c]=INV_SBOX[s[r][c]]

def inv_shift_rows(s):
    s[1]=[s[1][3],s[1][0],s[1][1],s[1][2]]
    s[2]=[s[2][2],s[2][3],s[2][0],s[2][1]]
    s[3]=[s[3][1],s[3][2],s[3][3],s[3][0]]

def inv_mix_columns(s):
    for c in range(4):
        a=[s[r][c] for r in range(4)]
        s[0][c]=mul(a[0],0x0e)^mul(a[1],0x0b)^mul(a[2],0x0d)^mul(a[3],0x09)
        s[1][c]=mul(a[0],0x09)^mul(a[1],0x0e)^mul(a[2],0x0b)^mul(a[3],0x0d)
        s[2][c]=mul(a[0],0x0d)^mul(a[1],0x09)^mul(a[2],0x0e)^mul(a[3],0x0b)
        s[3][c]=mul(a[0],0x0b)^mul(a[1],0x0d)^mul(a[2],0x09)^mul(a[3],0x0e)

def sub_bytes(s):
    for r in range(4):
        for c in range(4): s[r][c]=SBOX[s[r][c]]

def shift_rows(s):
    s[1]=[s[1][1],s[1][2],s[1][3],s[1][0]]
    s[2]=[s[2][2],s[2][3],s[2][0],s[2][1]]
    s[3]=[s[3][3],s[3][0],s[3][1],s[3][2]]

def mix_columns(s):
    for c in range(4):
        a=[s[r][c] for r in range(4)]
        s[0][c]=mul(a[0],2)^mul(a[1],3)^a[2]^a[3]
        s[1][c]=a[0]^mul(a[1],2)^mul(a[2],3)^a[3]
        s[2][c]=a[0]^a[1]^mul(a[2],2)^mul(a[3],3)
        s[3][c]=mul(a[0],3)^a[1]^a[2]^mul(a[3],2)

def encrypt_block(block, w):
    s=[[block[c*4+r] for c in range(4)] for r in range(4)]
    add_round_key(s,w,0)
    for rnd in range(1,14):
        sub_bytes(s); shift_rows(s); mix_columns(s); add_round_key(s,w,rnd)
    sub_bytes(s); shift_rows(s); add_round_key(s,w,14)
    return bytes(s[r][c] for c in range(4) for r in range(4))

def decrypt_block(block, w):
    s=[[block[c*4+r] for c in range(4)] for r in range(4)]
    add_round_key(s,w,14)
    for rnd in range(13,0,-1):
        inv_shift_rows(s); inv_sub_bytes(s); add_round_key(s,w,rnd); inv_mix_columns(s)
    inv_shift_rows(s); inv_sub_bytes(s); add_round_key(s,w,0)
    return bytes(s[r][c] for c in range(4) for r in range(4))

def main():
    data=sys.stdin.read().split('\n')
    key=bytes.fromhex(data[0].strip())
    iv=bytes.fromhex(data[1].strip())
    ct=base64.b64decode(data[2].strip())
    if len(ct)%16!=0 or len(ct)==0:
        print('Error: invalid ciphertext'); return
    w=key_expansion(key)
    pt=b''; prev=iv
    for i in range(0,len(ct),16):
        blk=ct[i:i+16]
        d=decrypt_block(blk,w)
        pt+=bytes(d[j]^prev[j] for j in range(16))
        prev=blk
    pad=pt[-1]
    if pad<1 or pad>16 or pt[-pad:]!=bytes([pad])*pad:
        print('Error: invalid padding'); return
    pt=pt[:-pad]
    sys.stdout.write(pt.decode('utf-8','replace'))

